//! Hand-written companions to the generated [`schema`](crate::schema).
//!
//! Diesel's `allow_columns_to_appear_in_same_group_by_clause!` must be declared
//! for columns from different tables that a query groups by together. It cannot
//! live in `schema.rs` (that file is regenerated by `diesel print-schema`), so
//! the usage analytics' cross-table `GROUP BY`s declare their column pairs here.

use crate::schema::{workspace_detection_call, workspace_detection_call_meter};

// Usage rollups group a model (from the call table) together with a meter (from
// the meter table): `GROUP BY call.model, meter.meter`.
diesel::allow_columns_to_appear_in_same_group_by_clause!(
    workspace_detection_call::model,
    workspace_detection_call_meter::meter,
);
